import React, { useState, Fragment } from 'react';
import PropTypes from 'prop-types';
import styled from 'styled-components';
import { Tabs, Message, Tooltip, Spin, Button } from 'oskari-ui';
import { GeneralTab, LayerFieldsTab, VisualizationTab } from './';
import { SecondaryButton, PrimaryButton, ButtonContainer } from 'oskari-ui/components/buttons';
import { ERRORS } from '../../constants';
import { MandatoryIcon } from 'oskari-ui/components/icons';
import { setDefaultFilter } from './layerAttributesHelper';

const Content = styled.div`
    margin: 12px 24px 24px;
`;
const Tab = styled('div')`
    width: 500px;
`;

const getValidationMessage = keys => {
    if (!keys.length) {
        return '';
    }
    return (
        <ul>
            { keys.map(key =>
                <li key={key}><Message messageKey={`flyout.validations.${key}`} /></li>) }
        </ul>
    );
};
const getTabTitle = (isValid, messageKey) => (
    <Fragment>
        <Message messageKey={messageKey}/>
        <MandatoryIcon isValid={isValid} style={{
            verticalAlign: '-0.25em',
            paddingLeft: '0.5em'
        }}/>
    </Fragment>
);

export const DEFAULT_FIELD = 'name';
export const DEFAULT_TYPE = 'String';

const getDefaultLayerFields = () => {
    return [{
        name: DEFAULT_FIELD,
        type: DEFAULT_TYPE
    }];
};

const getDefaultLocale = () => {
    const supported = Oskari.getSupportedLanguages();
    const localized = {};
    supported.forEach((key) => {
        const message = Oskari.getMsg('oskariui', `VectorLayerPresentation.attributes.locale.defaultNameProperty.${key}`, null, null);
        if (message) {
            localized[key] = {
                [DEFAULT_FIELD]: message
            };
        };
    });

    return localized;
};

const getDefaultAttributes = () => {
    return {
        data: {
            locale: getDefaultLocale()
        }
    };
};

export const LayerFormContent = ({ values, config, onOk, onCancel, error, addFeature }) => {
    // TODO: refactor this thing as it's getting way overly complicated
    const { maxSize, unzippedMaxSize, isImport } = config;
    const { style = Oskari.custom.generateBlankStyle(), locale = {} } = values || {};
    const layerFields = values?.id ? values?.layerFields || [] : getDefaultLayerFields();
    const initialAttributes = structuredClone(values?.id ? values?.attributes || {} : getDefaultAttributes());
    initialAttributes.data = initialAttributes.data || {};
    const storedVisibleFields = initialAttributes.data.filter?.default;
    const visibleFields = Array.isArray(storedVisibleFields)
        ? storedVisibleFields
        : layerFields.map(field => field.name);
    const attributes = setDefaultFilter(initialAttributes, layerFields, visibleFields);
    const [state, setState] = useState({
        id: values?.id,
        style,
        locale,
        loading: false,
        tab: 'general',
        file: values?.file,
        layerFields,
        attributes
    });

    const showSrs = isImport && error === ERRORS.NO_SRS;

    const updateStyle = (style) => setState({ ...state, style });

    const setTab = (tab) => setState({ ...state, tab });
    const updateState = (newState) => {
        const cloned = structuredClone(newState);
        setState({ ...state, ...cloned });
    };

    const onOkClick = () => {
        const values = {
            style: state.style,
            locale: state.locale,
            file: state.file,
            layerFields: state.layerFields,
            attributes: state.attributes
        };
        if (showSrs) {
            // add sourceSrs only if field is visible
            values.sourceSrs = state.sourceSrs;
        }
        onOk(values);
        setState({ ...state, loading: true });
    };

    const okBtnType = isImport ? 'import' : 'save';
    const languages = Oskari.getSupportedLanguages();
    const defaultLang = languages[0];
    const hasMandatoryName = Oskari.util.keyExists(state.locale, `${defaultLang}.name`) && state.locale[defaultLang].name.trim().length > 0;

    const validationKeys = isImport && !state.file ? ['file'] : [];
    if (!hasMandatoryName) {
        validationKeys.push('name');
    };

    if (showSrs && state.sourceSrs) {
        const { sourceSrs: srs } = state;
        // check that existing value is valid
        if (isNaN(srs) || srs.length < 4 || srs.length > 6) {
            validationKeys.push('epsg');
        }
    }

    if (!state?.layerFields?.length && !isImport) {
        validationKeys.push('layerFields');
    }

    const isValid = validationKeys.length === 0;
    const tabItems = [
        {
            key: 'general',
            label: getTabTitle(isValid, 'flyout.tabs.general'),
            children: (
                <Tab>
                    <GeneralTab
                        languages = {languages}
                        locale = {state.locale}
                        file = {state.file}
                        sourceSrs = {state.sourceSrs}
                        isImport = {isImport}
                        maxSize = {maxSize}
                        unzippedMaxSize = {unzippedMaxSize}
                        showSrs = {showSrs}
                        updateState = {updateState}
                    />
                </Tab>
            )
        },
        {
            key: 'visualization',
            label: <Message messageKey='flyout.tabs.visualization'/>,
            children: <Tab><VisualizationTab updateStyle={updateStyle} style={state.style} /></Tab>
        }
    ];

    if (!isImport) {
        tabItems.push({
            key: 'layerFields',
            label: getTabTitle(!!state?.layerFields?.length, 'flyout.tabs.layerFields'),
            children: <Tab><LayerFieldsTab
                id={state.id}
                layerFields={state.layerFields}
                attributes={state.attributes}
                updateParentState={updateState}/>
            </Tab>
        });
    };

    const Component = (
        <Content>
            <Tabs
                activeKey={state.tab}
                onChange={tabKey => setTab(tabKey)}
                items={tabItems}
            />
            <ButtonContainer>
                <Button onClick={() => addFeature()} disabled = {!state.id}>
                    <Message messageKey='featureEditor.featureLayer.addFeature'/>
                </Button>
                <SecondaryButton type='cancel' onClick={() => onCancel()}/>
                <Tooltip key="okButtonTooltip" title={ getValidationMessage(validationKeys) }>
                    <PrimaryButton disabled={!isValid} type={okBtnType} onClick={onOkClick}/>
                </Tooltip>
            </ButtonContainer>
        </Content>
    );
    if (!error && state.loading) {
        return <Spin showTip={true}>{Component}</Spin>;
    }
    return Component;
};

LayerFormContent.propTypes = {
    values: PropTypes.object,
    config: PropTypes.object.isRequired,
    onOk: PropTypes.func.isRequired,
    onCancel: PropTypes.func.isRequired,
    error: PropTypes.string
};
